Here are four more quiet cafés within a 20-minute walk, open Saturday afternoon, added right below the other cafés.

```svelte file=lib/MoreNearby.svelte
<script>
  import { Section, Action, Table, MapView, ask } from 'design';
  import BookmarkSimple from 'phosphor-svelte/lib/BookmarkSimple';
  import NavigationArrow from 'phosphor-svelte/lib/NavigationArrow';

  let saved = $state(false);

  const columns = ['Café', 'Walk', 'Noise', 'Open until'];
  const rows = [
    ['Thimbleleaf Coffee', '9 min', 'Quiet', '5:00 PM'],
    ['Copperwick House', '14 min', 'Quiet', '7:00 PM'],
    ['Marrowby Reading Café', '16 min', 'Very quiet', '5:30 PM'],
    ['Fernquill Kitchen', '19 min', 'Calm', '4:00 PM']
  ];

  const places = [
    { label: 'Home', sublabel: '27 Pellory Street' },
    { label: 'Thimbleleaf Coffee', sublabel: '3 Sorrelby Row · 9 min' },
    { label: 'Copperwick House', sublabel: '61 Hatchmere Road · 14 min' },
    { label: 'Marrowby Reading Café', sublabel: '8 Ivelock Court · 16 min' }
  ];
</script>

<Section title="More quiet cafés" kicker="Within 20 min walk · open Saturday afternoon">
  <Table {columns} {rows} pick={1} />
  <MapView {places} height={180} />
  <p class="m-text">Copperwick House is the best backup: quiet booths, open well past 4:00 PM, and only 14 minutes away.</p>
  <p class="m-meta">Fernquill Kitchen closes at 4:00 PM, right as you'd wrap up.</p>
  {#snippet actions()}
    <Action
      label={saved ? 'Saved as backup' : 'Save Copperwick as backup'}
      sublabel={saved ? '61 Hatchmere Road' : '14 min walk · open until 7:00 PM'}
      icon={BookmarkSimple}
      primary
      disabled={saved}
      onclick={() => (saved = true)}
    />
    <Action
      label="Directions to Copperwick"
      icon={NavigationArrow}
      onclick={() => ask('Walking directions from 27 Pellory Street to Copperwick House, 61 Hatchmere Road, 14 minutes', 'Directions to Copperwick')}
    />
  {/snippet}
</Section>
```

